/** Enabled browser admission refuses when its policy service is unavailable. */
private browserRequestRejection(req: IncomingMessage, upgrade: boolean): string | undefined {
  if (this.config.browserAccessGuard !== true) return undefined
  try {
    const guard = this.ctx.get('aukoraBrowserAccess') as {
      requestRejection(request: IncomingMessage, upgrade: boolean): unknown
    } | undefined
    if (guard === undefined) return 'browser-node:binding-guard-unavailable'
    const reason = guard.requestRejection(req, upgrade)
    if (reason === undefined) return undefined
    return typeof reason === 'string' && reason.length > 0
      ? reason
      : 'browser-node:binding-guard-unavailable'
  } catch {
    return 'browser-node:binding-guard-unavailable'
  }
}

